package ro.leo.visual;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Offline help, reflecting Leo's own controls and documented hardware limits. */
public final class HelpActivity extends LeoActivity {
 static final String[] TOPICS={"Harta tastelor și Home","Telefon și contacte","Ceas și alarme","Mesaje și șabloane","Muzică, versuri și oprire","Teme și stocare","Ce este disponibil?"};
 static final String[] TEXT={"Soft stânga: acțiunea scrisă jos în stânga. Soft dreapta: Înapoi sau Șterge, după editor.\n\nD-pad: navigare. OK: deschide sau alege. Listele Leo se derulează circular.\n\nHome: 0 Media curentă; 1 Căutare; 5 scurt Acces rapid. 2–9 lung: apelare rapidă configurată. * schimbă cardul, # îl deschide.\n\nÎn modul mouse, D-pad mută cursorul, OK face clic, * schimbă derularea și # oprește modul.",
 "În Telefon poți introduce numărul sau cifrele T9 ale numelui. Numerele recunoscute apar primele, cu fotografia disponibilă ori inițiale. OK pe rezultat alege contactul. Verde începe alegerea SIM-ului.\n\nAlăturarea fotografiei nu inițiază un apel. *#06# afișează local IMEI. Istoric și Statistici sunt file separate.\n\nApelurile și SMS pe SIM 1 au confirmări reale. SIM 2, DTMF și IMS/VoLTE/VoWiFi au scenarii separate încă de validat.",
 "Ceas: stânga/dreapta schimbă Ora, Alarme, Glob, Timer și Crono.\n\nAlarme: Opțiuni pentru editare și zile. Fără zile bifate: o dată. Amânarea 5/10/15 minute se alege din Opțiuni; când sună alarma, soft stânga amână și OK oprește.\n\nCeas de birou: Opțiuni din fila Ora. Sus/jos reglează numai luminozitatea ferestrei. OK comută păstrarea ecranului aprins. La ieșire revin regulile normale ale sistemului.",
 "În conversație: 5 deschide răspunsul. Opțiuni oferă detalii, redirecționare și căutare text/T9.\n\nÎn editor: Opțiuni → Inserează șablon. Poți crea până la 20 de texte scurte. Alegerea unui șablon completează editorul și nu trimite SMS.\n\nPentru trimitere alegi SIM-ul și confirmi explicit. Mesajele lungi pot fi împărțite în mai multe SMS-uri; contorul afișează segmentele.",
 "Player: OK/5 pauză sau redare; 4/6 piesa anterioară/următoare; stânga/dreapta caută 10 secunde; sus/jos volum.\n\nOpțiuni → Versuri locale. LRC UTF-8 lângă piesă, cu același nume: piesa.mp3 + piesa.lrc. Alternativ: Documente Leo / Lyrics sau Documents/LeoLyrics în memoria telefonului/card. Marcaje de forma [00:12.50]. OK comută urmărirea, sus/jos derulare manuală. Nu se descarcă versuri.\n\nOprirea temporizată oprește numai Muzica Leo. Reluarea ultimei sesiuni este la cerere; muzica nu pornește automat după boot. Un fișier șters sau un card absent poate împiedica reluarea.",
 "Personalizare → Colecții vizuale complete aplică aceleași culori în Home și aplicațiile Leo, inclusiv Telefon. Confirmarea elimină suprascrierile individuale de teme. Imaginile de fundal sunt păstrate.\n\nStocare → Analiză citește fișierele pe categorii și arată topul celor mari. Nu șterge automat. Salvare Leo schimbă exporturile Notițe și înregistrările noi. Download păstrează locația proprie.\n\nBackup are restaurare pe categorii. Copiile sunt personale și necriptate.",
 "Confirmate anterior pe acest aparat: pornire internă, taste/T9, SIM 1 apeluri și SMS, LTE, Wi-Fi/hotspot, MTP, difuzor/receptor, căști cu fir, A2DP, radio FM/RDS și vibrații.\n\nÎn lucru sau nevalidate complet: cameră, GPS, SIM 2 apeluri/SMS, VoLTE/VoWiFi și toate formatele media. Emailul și aplicațiile Android depind de server, permisiuni și compatibilitatea cu tastele.\n\nAcest ajutor descrie starea proiectului; nu efectuează un diagnostic complet al hardware-ului."};
 protected void onCreate(Bundle b){super.onCreate(b);if(getIntent().hasExtra("topic"))topic(Math.max(0,Math.min(TOPICS.length-1,getIntent().getIntExtra("topic",0))));else home();}
 private void home(){list("Ajutor Leo",Arrays.asList(TOPICS),0,new Choice(){public void pick(int n){topic(n);}},"Taste",new Runnable(){public void run(){map();}});}
 private void topic(final int n){begin(TOPICS[n]);ScrollView scroll=new ScrollView(this);scroll.addView(text(TEXT[n],16));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();left=new Runnable(){public void run(){Class<?>[] targets={MainActivity.class,PhoneActivity.class,ClockActivity.class,MessagesActivity.class,MusicLibraryActivity.class,PersonalizationActivity.class,DiagnosticActivity.class};startActivity(new Intent(HelpActivity.this,targets[n]));}};back=new Runnable(){public void run(){home();}};footer("Deschide","Derulează","Înapoi");}
 private void map(){begin("Tastele Leo");root.addView(new View(this){final Paint p=new Paint(3);void label(Canvas c,String s,int x,int y,int size){p.setColor(Color.WHITE);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(size);c.drawText(s,x,y,p);}void box(Canvas c,int l,int t,int r,int b,String s){p.setColor(palette.card);c.drawRoundRect(l,t,r,b,5,5,p);label(c,s,(l+r)/2,(t+b)/2+5,13);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(palette.background);box(c,6,8,78,47,"Opțiuni");box(c,162,8,234,47,"Înapoi");box(c,87,7,153,47,"↑");box(c,53,53,92,90,"←");box(c,96,53,144,90,"OK");box(c,148,53,187,90,"→");box(c,87,96,153,132,"↓");String[] a={"0 Media","1 Caută","5 Rapid"};for(int n=0;n<3;n++)box(c,6+n*78,149,78+n*78,186,a[n]);label(c,"Home · 2–9 lung: apelare rapidă",120,209,12);c.restore();}},new LinearLayout.LayoutParams(-1,0,1));back=new Runnable(){public void run(){home();}};footer("","Hartă Home","Înapoi");}
}
